"""Pure standalone renderer. Supplied cached values only; no IO or calculation."""
import json
def build(summary,views):
 if not isinstance(summary,dict)or not isinstance(views,dict):raise TypeError('Authenticated JSON dictionaries required')
 payload=json.dumps(dict(summary=summary,views=views),ensure_ascii=False,allow_nan=False,separators=(',',':'))
 for char,escape in (('&','\\u0026'),('<','\\u003c'),('>','\\u003e'),('\u2028','\\u2028'),('\u2029','\\u2029')):payload=payload.replace(char,escape)
 return HTML.replace('__PAYLOAD__',payload)
